#!/bin/sh
# The three accounts of the directory, created through its API once it answers: the MCP
# server's own account (mcp-server) and two users with different rights in Trino (alice,
# bob). Each password comes from the environment, generated by run.sh for each run; none
# is printed. Runs in the directory's image, which has curl and lldap_set_password.
set -eu
url=http://ldap:17170
for _ in $(seq 60); do
  curl -sf -o /dev/null "$url/health" && break
  sleep 1
done
token=$(curl -sf -X POST "$url/auth/simple/login" -H 'Content-Type: application/json' \
  -d "{\"username\": \"admin\", \"password\": \"$LDAP_ADMIN_PASSWORD\"}" \
  | sed -E 's/.*"token":"([^"]+)".*/\1/')
create() { # uid, first name, password
  query='mutation($user: CreateUserInput!) { createUser(user: $user) { id } }'
  user="{\"id\": \"$1\", \"email\": \"$1@example.org\", \"displayName\": \"$2\", \"firstName\": \"$2\", \"lastName\": \"Test\"}"
  curl -sf "$url/api/graphql" -H "Authorization: Bearer $token" -H 'Content-Type: application/json' \
    -d "{\"query\": \"$query\", \"variables\": {\"user\": $user}}" | grep -q "\"id\":\"$1\""
  LLDAP_USER_PASSWORD="$3" /app/lldap_set_password --base-url "$url" --token "$token" --username "$1" >/dev/null
  echo "directory: $1 created"
}
create mcp-server "MCP server" "$MCP_SERVER_PASSWORD"
create alice Alice "$ALICE_PASSWORD"
create bob Bob "$BOB_PASSWORD"
